  async timetableChanges({organizationId,timetableId}){const r=await this.database.query(`SELECT ch.id,ch.change_date,ch.reason,ch.changed_starts_at,ch.changed_ends_at,e.id AS entry_id,c.name AS class_name,s.name AS subject_name,trim(concat_ws(' ',sp.first_name,sp.last_name)) AS changed_teacher_name,rm.name AS changed_room_name FROM acad_timetable_changes ch JOIN acad_timetable_entries e ON e.id=ch.timetable_entry_id JOIN school_classes c ON c.id=e.class_id JOIN school_subjects s ON s.id=e.subject_id LEFT JOIN school_staff_profiles sp ON sp.organization_id=ch.organization_id AND sp.user_id=ch.changed_teacher_user_id LEFT JOIN acad_rooms rm ON rm.id=ch.changed_room_id WHERE ch.organization_id=$1 AND e.timetable_id=$2 AND ch.status='approved' ORDER BY ch.change_date DESC`,[organizationId,timetableId]);return camels(r.rows);}
  async workload({organizationId,timetableId}){const r=await this.database.query(`SELECT e.teacher_user_id,trim(concat_ws(' ',sp.first_name,sp.last_name)) AS teacher_name,e.starts_at,e.ends_at,e.lesson_count FROM acad_timetable_entries e LEFT JOIN school_staff_profiles sp ON sp.organization_id=e.organization_id AND sp.user_id=e.teacher_user_id WHERE e.organization_id=$1 AND e.timetable_id=$2 AND e.active=true`,[organizationId,timetableId]);const m=new Map();for(const x of r.rows){const o=m.get(x.teacher_user_id)||{teacherUserId:x.teacher_user_id,teacherName:x.teacher_name||x.teacher_user_id,lessons:0,minutes:0};o.lessons+=Number(x.lesson_count||1);const[sh,sm]=String(x.starts_at).split(':').map(Number),[eh,em]=String(x.ends_at).split(':').map(Number);o.minutes+=Math.max(0,eh*60+em-(sh*60+sm));m.set(x.teacher_user_id,o);}return[...m.values()].sort((a,b)=>b.minutes-a.minutes);}

