  async schemeWorkflow({organizationId,userId,id:schemeId,action,feedback=null,requestId=null}){const s=await this.owned('acad_schemes',schemeId,organizationId,'Scheme of work');const transitions={submit:{from:['draft','rejected'],to:'submitted_hod'},hod_approve:{from:['submitted_hod'],to:'submitted_dos'},dos_approve:{from:['submitted_dos'],to:'approved'},reject:{from:['submitted_hod','submitted_dos'],to:'rejected'},archive:{from:['draft','submitted_hod','submitted_dos','approved','rejected'],to:'archived'}};const x=transitions[action];if(!x||!x.from.includes(s.status))fail(409,'INVALID_STATUS',`Cannot ${action} this scheme from ${s.status}.`);let sql=`UPDATE acad_schemes SET status=$1,updated_at=now()`,vals=[x.to];if(action==='hod_approve'){vals.push(text(feedback),userId);sql+=`,hod_feedback=$2,hod_reviewed_by=$3,hod_reviewed_at=now()`;}else if(action==='dos_approve'){vals.push(text(feedback),userId);sql+=`,dos_feedback=$2,dos_approved_by=$3,dos_approved_at=now()`;}else if(action==='reject'){vals.push(text(feedback));sql+=s.status==='submitted_hod'?`,hod_feedback=$2`:` ,dos_feedback=$2`;}vals.push(schemeId,organizationId);sql+=` WHERE id=$${vals.length-1} AND organization_id=$${vals.length}`;await this.database.query(sql,vals);await this.snapshotScheme({organizationId,schemeId,userId,changeNote:`${action}${feedback?`: ${feedback}`:''}`});await this.database.query(`UPDATE acad_schemes SET version_no=version_no+1 WHERE id=$1 AND organization_id=$2`,[schemeId,organizationId]);await this.auditEvent({organizationId,actorId:userId,action:`academics.scheme.${action}`,entityType:'scheme',entityId:schemeId,details:{feedback},requestId});return this.schemeDetail({organizationId,id:schemeId});}

